namespace RepoContext.Core.Scanning;

/// <summary>
/// A gitignore-style path matcher. Used for <c>.gitignore</c>,
/// <c>.repoctxignore</c>, the config <c>exclude</c> list and
/// <c>sensitiveFiles</c>. Paths are relative to the repository root, use
/// <c>/</c> separators, and directory pruning during traversal handles
/// descendant semantics.
/// </summary>
public sealed class GitignoreMatcher
{
    private readonly record struct Rule(Regex Regex, bool Negate, bool DirOnly, bool Anchored);

    private readonly IReadOnlyList<Rule> _rules;

    private GitignoreMatcher(IReadOnlyList<Rule> rules) => _rules = rules;

    /// <summary>An empty matcher that ignores nothing.</summary>","receipt":"VZuqSsWXdaE6dG2-2KekOTCksUZ5KaEbIvukqjt3CCo"},{"start_line":24,"end_line":69,"symbol":"Parse","text":"    public static GitignoreMatcher Parse(IEnumerable<string> lines)
    {
        var rules = new List<Rule>();
        foreach (string raw in lines)
        {
            string line = raw.TrimEnd();
            if (line.Length == 0 || line.StartsWith('#'))
            {
                continue;
            }

            bool negate = false;
            if (line.StartsWith('!'))
            {
                negate = true;
                line = line[1..];
            }

            bool dirOnly = line.EndsWith('/');
            if (dirOnly)
            {
                line = line[..^1];
            }

            bool anchored = line.StartsWith('/');
            if (anchored)
            {
                line = line[1..];
            }

            // A slash anywhere (other than a trailing one) anchors the pattern.
            if (line.Contains('/'))
            {
                anchored = true;
            }

            if (line.Length == 0)
            {
                continue;
            }

            rules.Add(new Rule(GlobPattern.ToRegex(line), negate, dirOnly, anchored));
        }

        return new GitignoreMatcher(rules);
    }","receipt":"7DLZ6tFsHwJw1Md4aTOQC8hy7X4z44f5CLEX9fRAdlk"}]},{"path":"src/RepoContext.Core/Configuration/RepoctxConfig.cs","kind":"source","score":0.5338,"content_tokens":37,"projected_read_tokens":0,"estimated_tokens":154,"file_tokens":1928,"hash":"5f66fff20218","reasons":["fts","symbol:RespectGitignore","symbol:Exclude","imported-by:src/RepoContext.Core/Scanning/FileScanner.cs","mentioned-by:docs/cost-efficiency-implementation-plan.md","imported-by:src/RepoContext.Core/Configuration/Initializer.cs","graph:+63","mentions:repoctx.config.json"],"spans":[{"start_line":25,"end_line":25,"symbol":"Exclude","text":"    public IReadOnlyList<string> Exclude { get; init; } = [];","receipt":"YRlM3wJXNO3o3BJ4cYwYAAfvPR-aTqTPGzZIoM9BjuY"},{"start_line":27,"end_line":27,"symbol":"RespectGitignore","text":"    public bool RespectGitignore { get; init; } = true;","receipt":"28gcODp9i8wNEebSEhZ1XCIj9sw_u1R-BJyYE5CFEOs"}]},{"path":"repocontext-produktdoku.md","kind":"doc","score":0.4375,"start_line":127,"end_line":138,"content_tokens":132,"projected_read_tokens":0,"estimated_tokens":291,"file_tokens":3897,"hash":"ca92b73b65ed","receipt":"0dF-74fiJq8UkbBSOl3XqIad6ohDi16C3E20Pkw9QBk","reasons":["fts","mentions:README.md","mentioned-by:docs/decisions/0017-whole-repository-coverage.md","mentioned-by:docs/build-prompt.md","mentions:repoctx.config.json","mentions:tests/fixtures/sample-cs/Services/UserService.cs","mentions:tests/fixtures/sample-ts/src/auth/__tests__/login.test.ts","mentions:tests/fixtures/sample-ts/src/auth/permissions.ts","mentions:tests/fixtures/sample-ts/src/middleware.ts","mentioned-by:docs/decisions/0003-source-of-truth.md"],"spans":[{"start_line":127,"end_line":138,"text":"## 7. Tokenverbrauch

